    created() {
        const query = this.$route.query;
        this.selectedCategories = Object.keys(query)
            .filter((key) => key.startsWith("cat["))
            .map((key) => query[key]);

        this.selectedFilter = query.filter || "";
        this.searchKey = query.search || "";

        const ssr = this.ssrDiscussBootstrap;
        const payload = ssr && typeof ssr === 'object' && 'value' in ssr ? ssr.value : ssr;
        const hasQuery = Object.keys(query || {}).length > 0;
        if (!payload || hasQuery) return;
        if (Array.isArray(payload.questions)) {
            this.questions = payload.questions;
            this.currentPage = (payload.pagination?.current_page || 1) + 1;
            this.lastPage = payload.pagination?.last_page || null;
            this.initLoadingQuestions = false;
            this.mounted = true;
        }
        if (payload.initData) {
            this.initData = payload.initData;
            this.initLoadingSidebar = false;
        }
    },
    methods: {
        getInitData() {
            axiosInstance
                .post("/discuss/layouts/getInitData")
                .then((response) => {
                    this.initData = response.data.initData;
                })
                .catch((error) => {
                    console.error(error.response.data.errors);
                })
                .finally(() => {
                    this.initLoadingSidebar = false;
                });
        },
        buildQueryParams() {
            let params = {
                page: this.currentPage,
            };

            if (this.selectedFilter && this.selectedFilter !== "all") {
                params.filter = this.selectedFilter;
            }

            if (this.selectedCategories.length) {
                params.cat = this.selectedCategories;
            }

            if (this.searchKey) {
                params.search = this.searchKey;
            }

            return params;
        },

        async getQuestions(loadMore = false) {
            if (this.loading || (this.lastPage && this.currentPage > this.lastPage)) return;

            if (this.mounted) this.loading = true;

            try {
                const params = this.buildQueryParams();
                const response = await axiosInstance.post("/discuss", params);

                if (loadMore) {
                    this.questions.push(...response.data.questions);
                } else {
                    this.questions = response.data.questions;
                }

                this.currentPage = response.data.pagination.current_page + 1;
                this.lastPage = response.data.pagination.last_page;
            } catch (error) {
                console.error("Error loading questions:", error);
            } finally {
                this.loading = false;
                this.searchLoading = false;
                this.mounted = true;
                this.initLoadingQuestions = false;
            }
        },

        deleteSearchKey() {
            this.searchKey = "";
            this.searchFor = "";
            this.handleFilterChange({ search: this.searchKey });
        },

        handleSearch: debounce(function () {
            if (this.searchKey.trim() === this.searchFor) {
                return;
            }

            if (this.searchKey.trim().length > 2) {
                this.searchLoading = true;
                this.searchFor = this.searchKey.trim();
                this.handleFilterChange({ search: this.searchKey });
            } else if (this.searchKey.length === 0) {
                this.searchLoading = true;
                this.searchFor = "";
                this.handleFilterChange({});
            }
        }, 1000),

        handleFilterChange(filter) {
            // this.filterLoading = true;

            if (filter.filterType === "categories") {
                this.selectedCategories = filter.value;
            } else if (filter.filterType === "filter") {
                this.selectedFilter = filter.value;
            } else if (filter.filterType === "search") {
                this.searchKey = filter.value;
            }

            let query = "";

            if (this.selectedFilter && this.selectedFilter !== "all") {
                query += `filter=${this.selectedFilter}&`;
            }

            if (this.selectedCategories.length) {
                this.selectedCategories.forEach((category, index) => {
                    query += `cat[${index}]=${category}&`;
                });
            }

            if (this.searchKey && this.searchKey !== "") {
                query += `search=${this.searchKey}&`;
            }

            query = query.slice(0, -1);
            const newUrl = query ? `${window.location.pathname}?${query}` : window.location.pathname;
            // Preserve Vue Router history.state or named navigations stop working.
            window.history.pushState({ ...window.history.state }, "", newUrl);

            this.currentPage = 1;
            this.getQuestions(false);

            // setTimeout(() => {
            // 	this.filterLoading = false;
            // }, 1000);
        },

        handleScroll() {
            const questionContainer = this.$refs.questionContainer;
            if (!questionContainer) return;
            const rect = questionContainer.getBoundingClientRect();

            if (rect.bottom <= window.innerHeight - 30 && !this.hasReachedEnd) {
                // default is (+10)
                this.getQuestions(true);
                this.hasReachedEnd = true;
            }

            if (rect.bottom > window.innerHeight) {
                this.hasReachedEnd = false;
            }
        },
    },
    mounted() {
        // Setup SEO with static keywords
        useSEO({
            title: this.$t('discuss.list.seoTitle'),
            description: this.$t('discuss.list.seoDescription'),
            url: "/discuss",
            keywords: [
                this.$t('discuss.list.seoTitle'),
                this.$t('discuss.list.seoKeyword.programmingQuestions'),
                this.$t('discuss.list.seoKeyword.programmingForum'),
                'Q&A',
                this.$t('discuss.list.seoKeyword.debugging'),
                this.$t('discuss.list.seoKeyword.laravelErrors'),
                this.$t('discuss.list.seoKeyword.vueErrors'),
                this.$t('discuss.list.seoKeyword.reactErrors'),
                this.$t('discuss.list.seoKeyword.phpQuestions'),
                this.$t('discuss.list.seoKeyword.jsQuestions'),
                this.$t('discuss.list.seoKeyword.pythonQuestions'),
                this.$t('discuss.list.seoKeyword.programmingHelp'),
                this.$t('discuss.list.seoKeyword.codingGuidance')
            ]
        });
         
        if (this.initLoadingSidebar) this.getInitData();
        if (this.initLoadingQuestions) this.getQuestions(false);

        window.addEventListener("scroll", this.handleScroll);
    },
    beforeUnmount() {
        window.removeEventListener("scroll", this.handleScroll);
    },
};
</script>

<style>
html {
    scroll-behavior: smooth;
}
</style>
